UPDATE posts SET body_html = replace(body_html, '<h2>Why Cats Need Moving, Filtered Water</h2>', '<figure style="margin:40px 0;text-align:center"><img src="/img/cat-hydration-tips.jpg" alt="Infographic: 5 hydration tips every cat owner should know - fresh water daily, feed wet food, do not rely on dry food alone, use a pet water fountain, keep cats cool, plus dehydration warning signs" style="max-width:100%;border-radius:12px;box-shadow:0 8px 24px rgba(26,20,16,.12)"><figcaption style="font-size:13px;color:#3d322a;font-style:italic;margin-top:10px">Save or share our quick-reference hydration guide.</figcaption></figure><h2>Why Cats Need Moving, Filtered Water</h2>'), updated_at = '2026-08-13T10:40:00.000Z' WHERE id = 3 AND body_html NOT LIKE '%cat-hydration-tips%';